// Hand-written `@trpc/client` stub for the flowatlas fixture suite.
//
// The client is typed from the router type it is handed, as the library's is:
// a query procedure is a member with `query(input)`, a mutation one with
// `mutate(input)`, each answering what the procedure answers (P256). A client
// handed `any` is `any`. The last link of the chain is the one that sends.
//
// It declares less than the library: no subscriptions, no transformers. It
// declares nothing of a different kind.

import type { MutationProcedure, QueryProcedure, Router } from '@trpc/server';

export interface TRPCLink {
  readonly _link: true;
}

export declare function httpBatchLink(options: { url: string | (() => string) }): TRPCLink;
export declare function httpLink(options: { url: string | (() => string) }): TRPCLink;

type Decorated<Record> = {
  [Key in keyof Record]: Record[Key] extends QueryProcedure<infer Input, infer Output>
    ? { query(input: Input): Promise<Output> }
    : Record[Key] extends MutationProcedure<infer Input, infer Output>
      ? { mutate(input: Input): Promise<Output> }
      : Record[Key] extends Router<infer Inner>
        ? Decorated<Inner>
        : never;
};

/** A client of a router, typed from the router's own type. */
export type TRPCClient<R> = R extends Router<infer Record> ? Decorated<Record> : any;

export declare function createTRPCClient<R = any>(options: { links: TRPCLink[] }): TRPCClient<R>;
